:root {
  --bg: #0b1220;
  --panel: rgba(255, 255, 255, 0.06);
  --border: rgba(255, 255, 255, 0.10);
  --text: rgba(255, 255, 255, 0.92);
  --muted: rgba(255, 255, 255, 0.70);
  --brandA: #8b5cf6;
  --brandB: #06b6d4;
  --shadow: 0 18px 70px rgba(0, 0, 0, 0.35);
  --radius: 18px;

  color-scheme: dark;
  font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, "Helvetica Neue", Arial;
  background: var(--bg);
  color: var(--text);
}

:root[data-theme="light"] {
  --bg: #f8fafc;
  --panel: rgba(15, 23, 42, 0.04);
  --border: rgba(15, 23, 42, 0.12);
  --text: rgba(15, 23, 42, 0.92);
  --muted: rgba(15, 23, 42, 0.70);
  --shadow: 0 16px 55px rgba(2, 6, 23, 0.12);
  color-scheme: light;
}

* { box-sizing: border-box; }

html, body, #root {
  height: 100%;
  margin: 0;
}

body {
  background:
    radial-gradient(circle at top left, color-mix(in srgb, var(--brandA) 35%, transparent), transparent 40%),
    radial-gradient(circle at top right, color-mix(in srgb, var(--brandB) 28%, transparent), transparent 38%),
    var(--bg);
}

a { color: inherit; }

.app { min-height: 100%; display: flex; flex-direction: column; }

.topbar {
  position: sticky;
  top: 0;
  z-index: 10;
  backdrop-filter: blur(14px);
  background: color-mix(in srgb, var(--bg) 80%, transparent);
  border-bottom: 1px solid var(--border);
  display: flex;
  gap: 16px;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
}

.brand { min-width: 0; }
.brandTitle { font-weight: 900; letter-spacing: -0.02em; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.brandSub { font-size: 12px; color: var(--muted); max-width: 520px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.nav { display: flex; gap: 8px; flex-wrap: wrap; justify-content: center; }
.navLink {
  font-size: 13px;
  padding: 8px 10px;
  border-radius: 999px;
  border: 1px solid transparent;
  text-decoration: none;
  color: var(--muted);
}
.navLink.active { color: var(--text); border-color: var(--border); background: var(--panel); }

.container { width: min(1120px, calc(100% - 28px)); margin: 0 auto; padding: 22px 0 52px; flex: 1; }

.footer { border-top: 1px solid var(--border); padding: 18px 0; }
.footerInner { width: min(1120px, calc(100% - 28px)); margin: 0 auto; display: flex; gap: 12px; justify-content: space-between; align-items: center; }
.footerLink { opacity: 0.8; text-decoration: none; }
.footerLink:hover { opacity: 1; text-decoration: underline; }

.btn {
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 10px 14px;
  background: var(--panel);
  color: var(--text);
  font-weight: 800;
  cursor: pointer;
}
.btn:focus-visible { outline: 3px solid color-mix(in srgb, var(--brandB) 65%, transparent); outline-offset: 2px; }
.btnPrimary { border: none; background: linear-gradient(135deg, var(--brandA), var(--brandB)); }
.btnGhost { background: transparent; }

.stack { display: grid; gap: 16px; }
.row { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }
.grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 14px; }

.hero { border: 1px solid var(--border); background: var(--panel); border-radius: calc(var(--radius) + 8px); box-shadow: var(--shadow); overflow: hidden; }
.heroInner { padding: 26px; }
.pill { display: inline-flex; padding: 6px 10px; border-radius: 999px; background: color-mix(in srgb, var(--brandA) 18%, transparent); border: 1px solid color-mix(in srgb, var(--brandA) 22%, transparent); font-size: 12px; font-weight: 800; margin-bottom: 10px; }
.heroTitle { margin: 0; font-size: clamp(2.1rem, 5vw, 3.4rem); letter-spacing: -0.03em; }
.heroLead { margin: 10px 0 0; color: var(--muted); line-height: 1.7; max-width: 62ch; }

.pageTitle { margin: 0; font-size: 1.8rem; letter-spacing: -0.02em; }

.card { border: 1px solid var(--border); border-radius: var(--radius); background: var(--panel); padding: 18px; }
.eyebrow { display: inline-flex; font-size: 12px; font-weight: 900; opacity: 0.85; }
.cardTitle { margin: 10px 0 8px; font-size: 1.05rem; }
.cardBody { color: var(--muted); line-height: 1.7; }

.toolbar { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; justify-content: space-between; }
.input {
  flex: 1;
  min-width: 240px;
  max-width: 520px;
  border-radius: 12px;
  border: 1px solid var(--border);
  padding: 10px 12px;
  background: color-mix(in srgb, var(--bg) 92%, transparent);
  color: var(--text);
}
.input:focus-visible { outline: 3px solid color-mix(in srgb, var(--brandA) 60%, transparent); outline-offset: 2px; }

.list { margin: 10px 0 0; padding-left: 18px; color: var(--muted); display: grid; gap: 6px; }
.link { color: var(--text); }
.link:hover { text-decoration: underline; }
.muted { color: var(--muted); }
.pre { white-space: pre-wrap; margin: 0; font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace; font-size: 13px; }

@media (max-width: 720px) {
  .topbar { align-items: stretch; flex-direction: column; }
  .nav { justify-content: flex-start; }
  .topbarActions { align-self: flex-start; }
  .footerInner { align-items: flex-start; flex-direction: column; }
  .heroInner { padding: 20px; }
  .heroTitle { font-size: 2.1rem; }
}


.templateHero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 18px;
  border: 1px solid var(--border);
  border-radius: 16px;
  background: var(--panel);
  box-shadow: var(--shadow);
}
.templateMetrics {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 14px;
}
.templateDelta {
  display: inline-flex;
  color: #22c55e;
  font-weight: 800;
}
.templatePanel {
  display: grid;
  gap: 14px;
  padding: 16px;
  border: 1px solid var(--border);
  border-radius: 16px;
  background: var(--panel);
  box-shadow: var(--shadow);
}
.templatePanelHeader {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}
.templatePanelHeader h2 {
  margin: 0;
  font-size: 1.1rem;
}
.templatePanelHeader p {
  margin: 4px 0 0;
  color: var(--muted);
}
.templateBadge,
.statusPill {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  border-radius: 999px;
  padding: 5px 8px;
  background: color-mix(in srgb, var(--brandA) 14%, transparent);
  border: 1px solid color-mix(in srgb, var(--brandA) 24%, transparent);
  color: var(--text);
  font-size: 12px;
  font-weight: 800;
}
.statusPill.blocked { background: color-mix(in srgb, #ef4444 16%, transparent); border-color: color-mix(in srgb, #ef4444 28%, transparent); }
.statusPill.pending { background: color-mix(in srgb, #f59e0b 16%, transparent); border-color: color-mix(in srgb, #f59e0b 28%, transparent); }
.templateTable {
  display: grid;
  gap: 8px;
}
.templateTableRow {
  display: grid;
  grid-template-columns: 1.1fr 1.5fr 1fr 1fr 0.8fr;
  gap: 10px;
  align-items: center;
  padding: 11px 12px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: color-mix(in srgb, var(--panel) 88%, transparent);
}
.templateTableRow span,
.templateTableRow em {
  color: var(--muted);
  font-style: normal;
}
.templateSplit {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 14px;
}
.templateTextarea {
  width: 100%;
  min-height: 150px;
  resize: vertical;
  border-radius: 12px;
  border: 1px solid var(--border);
  padding: 12px;
  background: color-mix(in srgb, var(--bg) 92%, transparent);
  color: var(--text);
}
.templateResult {
  display: grid;
  gap: 8px;
  min-height: 150px;
  align-content: start;
  padding: 12px;
  border-radius: 12px;
  background: color-mix(in srgb, var(--brandA) 9%, transparent);
}
.templateList {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.templateList span {
  padding: 8px 10px;
  border-radius: 999px;
  border: 1px solid var(--border);
  color: var(--muted);
}
.portfolioHero {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(220px, 0.85fr);
  gap: 18px;
  align-items: stretch;
  padding: 22px;
  border-radius: 18px;
  border: 1px solid var(--border);
  background:
    radial-gradient(circle at 84% 24%, color-mix(in srgb, var(--brandA) 20%, transparent), transparent 34%),
    var(--panel);
  box-shadow: var(--shadow);
}
.portfolioPortrait {
  min-height: 220px;
  display: grid;
  align-content: end;
  gap: 14px;
  padding: 18px;
  border-radius: 18px;
  background: linear-gradient(135deg, color-mix(in srgb, var(--brandA) 22%, transparent), color-mix(in srgb, var(--brandB) 16%, transparent));
  border: 1px solid var(--border);
}
.portfolioPortrait span {
  width: 70px;
  height: 70px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 24px;
  background: var(--text);
  color: var(--bg);
  font-size: 34px;
  font-weight: 900;
}
.portfolioPortrait strong {
  max-width: 220px;
  font-size: 1.35rem;
  line-height: 1.05;
}
.portfolioProjectGrid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}
@media (max-width: 760px) {
  .templateHero,
  .templatePanelHeader {
    flex-direction: column;
  }
  .templateSplit,
  .templateTableRow,
  .portfolioHero,
  .portfolioProjectGrid {
    grid-template-columns: 1fr;
  }
}

